// Loaded by every page of this site, first thing in <head> (before the styles), so it can act before the page is drawn.
// Site-wide behaviour goes here (e.g. redirecting old addresses), then no page has to be touched.
// Pages are generated by tools/generate.py; the hand-written pages (docs/pa/, docs/fonts/, docs/shelf/) load it the same way.
(function () {
  // Texts with IDS sequences (docs/shelf/): draw them as glyphs with KAGE (ids.js), only on pages that have them
  document.addEventListener('DOMContentLoaded', function () {
    if (!document.querySelector('span.ids[data-ids]')) return;
    function load(src, done) { var s = document.createElement('script'); s.src = src; s.onload = done; document.head.appendChild(s); }
    load('https://qatt.org/js/kage-engine.min.js', function () { load('/pages/ids.js', function () { window.IdsGlyphs.run(); }); });
  });
})();
